begin read only;
set local statement_timeout='20s';
select json_build_object('settings',json_build_object('enabled',s.enabled,'access_tier',s.access_tier,'standard_verified_at',s.standard_verified_at)) from pinterest_publish_settings s;
select json_build_object('rules',json_build_object('max_posts_per_day',r.max_posts_per_day,'min_gap_hours',r.min_gap_hours,'evergreen_reuse_days',r.evergreen_reuse_days)) from promotion_rules r where r.platform='pinterest' group by r.max_posts_per_day,r.min_gap_hours,r.evergreen_reuse_days;
select json_build_object('account',a.account_name,'handle',a.handle,'status',a.account_status,'category',cv.board_or_category,'drafts',count(*),'with_image',count(cv.image_url)) from publish_queue q join social_accounts a on a.id=q.social_account_id join content_variants cv on cv.id=q.content_variant_id where a.handle in ('sailing_981','icyndizhang','mydecorshop','cindyzhang62','ivy5205') and q.platform='pinterest' and q.status='draft' group by a.account_name,a.handle,a.account_status,cv.board_or_category;
select json_build_object('candidate',json_build_object('queue_id',q.id,'shop',s.shop_name,'listing_id',p.etsy_listing_id,'source_url',p.etsy_url,'category',cv.board_or_category,'image_url',cv.image_url,'destination_url',cv.destination_url,'title',cv.title,'body',cv.body,'handle',a.handle,'mapped',exists(select 1 from shop_social_accounts m where m.shop_id=q.shop_id and m.social_account_id=q.social_account_id and m.active),'history_count',(select count(*) from publish_history h where h.product_id=q.product_id and h.platform='pinterest'),'review_exists',exists(select 1 from pinterest_publish_reviews r where r.queue_id=q.id))) from publish_queue q join social_accounts a on a.id=q.social_account_id join content_variants cv on cv.id=q.content_variant_id join products p on p.id=q.product_id join shops s on s.id=q.shop_id where a.handle in ('sailing_981','icyndizhang','mydecorshop','cindyzhang62','ivy5205') and q.platform='pinterest' and q.status='draft' and (cv.image_url is not null or a.handle in ('sailing_981','mydecorshop','cindyzhang62','ivy5205')) order by s.shop_name,p.etsy_listing_id limit 50;
select json_build_object('account_readiness',json_build_object('account',a.account_name,'handle',a.handle,'status',a.account_status,'active',a.active,'oauth_connected',exists(select 1 from pinterest_oauth_credentials c where c.social_account_id=a.id),'drafts',(select count(*) from publish_queue q where q.social_account_id=a.id and q.status='draft'),'drafts_with_image',(select count(*) from publish_queue q join content_variants cv on cv.id=q.content_variant_id where q.social_account_id=a.id and q.status='draft' and cv.image_url is not null))) from social_accounts a where a.platform='pinterest' order by a.account_name;
select json_build_object('p1_publication',json_build_object('queue_id',q.id,'listing_id',p.etsy_listing_id,'queue_status',q.status,'attempt_state',a.state,'pin_id',a.pin_id,'error',a.error_code,'history_pin_id',h.external_post_id,'history_url',h.external_url,'published_at',h.published_at,'snapshot_matches',r.snapshot=public.pinterest_publish_snapshot(q.id))) from publish_queue q join social_accounts sa on sa.id=q.social_account_id join products p on p.id=q.product_id left join pinterest_publish_reviews r on r.queue_id=q.id left join pinterest_publish_attempts a on a.queue_id=q.id left join publish_history h on h.content_variant_id=q.content_variant_id and h.platform='pinterest' where sa.handle='icyndizhang' and r.queue_id is not null;
select json_build_object('p3_publication',json_build_object('queue_id',q.id,'listing_id',p.etsy_listing_id,'queue_status',q.status,'attempt_state',a.state,'pin_id',a.pin_id,'error',a.error_code,'history_pin_id',h.external_post_id,'history_url',h.external_url,'published_at',h.published_at,'snapshot_matches',r.snapshot=public.pinterest_publish_snapshot(q.id))) from publish_queue q join social_accounts sa on sa.id=q.social_account_id join products p on p.id=q.product_id left join pinterest_publish_reviews r on r.queue_id=q.id left join pinterest_publish_attempts a on a.queue_id=q.id left join publish_history h on h.content_variant_id=q.content_variant_id and h.platform='pinterest' where sa.handle='mydecorshop' and r.queue_id is not null;
select json_build_object('p4_publication',json_build_object('queue_id',q.id,'listing_id',p.etsy_listing_id,'queue_status',q.status,'attempt_state',a.state,'pin_id',a.pin_id,'error',a.error_code,'history_pin_id',h.external_post_id,'history_url',h.external_url,'published_at',h.published_at,'snapshot_matches',r.snapshot=public.pinterest_publish_snapshot(q.id))) from publish_queue q join social_accounts sa on sa.id=q.social_account_id join products p on p.id=q.product_id left join pinterest_publish_reviews r on r.queue_id=q.id left join pinterest_publish_attempts a on a.queue_id=q.id left join publish_history h on h.content_variant_id=q.content_variant_id and h.platform='pinterest' where sa.handle='cindyzhang62' and r.queue_id is not null;
select json_build_object('p5_publication',json_build_object('queue_id',q.id,'listing_id',p.etsy_listing_id,'queue_status',q.status,'attempt_state',a.state,'pin_id',a.pin_id,'error',a.error_code,'history_pin_id',h.external_post_id,'history_url',h.external_url,'published_at',h.published_at,'snapshot_matches',r.snapshot=public.pinterest_publish_snapshot(q.id))) from publish_queue q join social_accounts sa on sa.id=q.social_account_id join products p on p.id=q.product_id left join pinterest_publish_reviews r on r.queue_id=q.id left join pinterest_publish_attempts a on a.queue_id=q.id left join publish_history h on h.content_variant_id=q.content_variant_id and h.platform='pinterest' where sa.handle='ivy5205' and r.queue_id is not null;
select json_build_object('shop_queue_coverage',json_build_object('account',a.account_name,'shop',s.shop_name,'ready',count(*) filter(where q.status in ('ready','scheduled') and r.snapshot=pinterest_publish_snapshot(q.id) and r.listing_checked_at>=now()-interval '30 days'),'published',count(*) filter(where q.status='published'),'paused_or_failed',count(*) filter(where q.status in ('paused','failed')),'latest_published_at',(select max(h.published_at) from publish_history h where h.shop_id=s.id and h.social_account_id=a.id and h.platform='pinterest'))) from publish_queue q join shops s on s.id=q.shop_id join social_accounts a on a.id=q.social_account_id left join pinterest_publish_reviews r on r.queue_id=q.id where q.platform='pinterest' and a.handle in ('icyndizhang','sailing_981','mydecorshop','cindyzhang62','ivy5205') group by a.id,a.account_name,s.id,s.shop_name order by a.account_name,s.shop_name;
commit;
